import { EntityTfError } from "../../engine/entity.js";
import { expr, scopedResourceLabel, tsLabelToTfLabel } from "../../engine/tf/index.js";
import { APP_RESOURCE_TYPE } from "../app/module.js";
import { AGENT_RESOURCE_TYPE } from "../agent/module.js";
import { PHONE_PROVIDER_ORG_BAG } from "../org/phone-provider.js";
import { PHONE_SERVICE_RESOURCE_TYPE } from "./module.js";
export function phoneServiceToTf(entity, opts) {
    if (entity.kind !== "phone-service") {
        throw new EntityTfError(`phoneServiceToTf expects kind "phone-service"; got "${entity.kind}"`);
    }
    const service = entity.payload;
    if (service === null || service.app?.refName !== opts.appRefName) {
        throw new EntityTfError(`phone service "${entity.refName}" does not reference owning app "${opts.appRefName}"`);
    }
    const agentRefName = service.agent?.refName;
    if (agentRefName === undefined || service.agent?.parent !== opts.appRefName) {
        throw new EntityTfError(`phone service "${entity.refName}" does not reference an agent owned by app "${opts.appRefName}"`);
    }
    const providerKey = service.provider?.refName ?? "";
    const provider = opts.orgRefs.byTsLabel(PHONE_PROVIDER_ORG_BAG, providerKey);
    if (provider === undefined) {
        throw new EntityTfError(`phone service "${entity.refName}": provider token "${providerKey}" is not in org.phoneProviders — re-run \`elementum pull org --data-only\``);
    }
    const label = scopedResourceLabel(opts.appTfLabel, tsLabelToTfLabel(entity.refName), "app");
    const attrs = {
        app_id: expr.resourceAttr(APP_RESOURCE_TYPE, opts.appTfLabel, ["id"]),
        provider_id: expr.dataAttr("elementum_phone_provider", provider.tfLabel, ["id"]),
        agent_id: expr.resourceAttr(AGENT_RESOURCE_TYPE, scopedResourceLabel(opts.appTfLabel, tsLabelToTfLabel(agentRefName), "app"), ["id"]),
    };
    if (service.callerAccessMode !== undefined)
        attrs["caller_access_mode"] = service.callerAccessMode;
    if (service.twilioExistingNumber !== undefined) {
        attrs["twilio_existing_number"] = { phone_number: service.twilioExistingNumber.phoneNumber ?? "" };
    }
    if (service.twilioNewNumber !== undefined) {
        attrs["twilio_new_number"] = { area_code: service.twilioNewNumber.areaCode ?? 0 };
    }
    if (service.registration !== undefined) {
        const registration = {};
        if (service.registration.generateFirstMessage !== undefined)
            registration["generate_first_message"] = service.registration.generateFirstMessage;
        if (service.registration.expandLanguages !== undefined)
            registration["expand_languages"] = service.registration.expandLanguages;
        if (service.registration.defaultLanguage !== undefined)
            registration["default_language"] = service.registration.defaultLanguage;
        if (service.registration.enableLanguageRouting !== undefined)
            registration["enable_language_routing"] = service.registration.enableLanguageRouting;
        if (service.registration.preferredLanguages !== undefined)
            registration["preferred_languages"] = [...service.registration.preferredLanguages];
        attrs["registration"] = registration;
    }
    const block = { kind: "resource", type: PHONE_SERVICE_RESOURCE_TYPE, label, attrs };
    return { blocks: [block], address: `${PHONE_SERVICE_RESOURCE_TYPE}.${label}` };
}
